import numpy as np
def dot(a, b):
    return np.sum(a * b)

result = dot(np.array([1, 2, 3]), np.array([4, 5, 6]))

import numpy as np
def cosine_similarity(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

a = np.array([1.0, 2.0, 2.0])
b = np.array([2.0, 4.0, 4.0])
sim = cosine_similarity(a, b)

